/**
 * Workbench-side mirrors of the pydantic VisionEvent / IRTarget models.
 *
 * Why duplicate vs importing from `./ir.ts`?
 * - `ir.ts` is regenerated by `pnpm gen:types`. This file lets the frontend
 *   compile and run against a fresh checkout *before* anyone runs codegen.
 * - The pydantic IR remains the source of truth — CI's type-sync job blocks
 *   any drift between this file and the generated zod schema.
 */

export type VisionEventSource =
  | "vlm"
  | "cv"
  | "asr"
  | "audio"
  | "text_llm"
  | "system";

export type IRTargetType =
  | "TemplateIR"
  | "ProjectIR"
  | "TranscriptLedger"
  | "Phase1AReport";
export type IRTargetOp = "set" | "append" | "remove";

export interface IRTarget {
  ir_type: IRTargetType;
  path: string;
  field?: string | null;
  op?: IRTargetOp;
}

export interface VisionEvent {
  event_id: string;
  task_id: string;
  sequence: number;
  timestamp: string;
  duration_ms: number;
  source: VisionEventSource;
  model_used: string | null;
  stage: string;
  frame_ts: number | null;
  frame_url: string | null;
  bbox_norm: [number, number, number, number] | null;
  semantic_label: string;
  reasoning: string;
  confidence: number;
  ir_target: IRTarget | null;
  // ir_value mirrors the backend's Any-typed field — it can be a scalar
  // (string/number/boolean), a list, or a nested object depending on
  // ir_target.path. The frontend's lodash.set treats it opaquely.
  ir_value: unknown;
  parent_event_id: string | null;
  cost_tokens: number | null;
  confidence_warning: boolean;
  severity: "info" | "warning" | "error";
}

export interface ScenarioListItem {
  name: string;
  description: string;
  event_count: number;
}
